import io
import os
import uuid
import re
from typing import Dict, Any, List, Tuple, Optional
from PIL import Image, ImageChops, ImageEnhance
from app.config import settings

SUSPICIOUS_SOFTWARE_KEYWORDS = [
    "photoshop", "gimp", "canva", "coreldraw", "illustrator",
    "pdfescape", "sejda", "ilovepdf", "smallpdf", "paint.net", "acrobat distiller"
]

AI_GENERATOR_KEYWORDS = [
    "midjourney", "stable diffusion", "dall-e", "dalle", "comfyui",
    "novelai", "firefly", "bing image creator", "flux.1", "civitai",
    "automatic1111", "invokeai", "generated by ai"
]

class TamperingDetector:
    """
    Forensic image and document authenticity screening engine.
    Screens for:
    - AI-generated synthetic document imagery & metadata
    - Digital image manipulation, compositing, or ELA compression anomalies
    - Inconsistent fonts, layout spacing, or visual structure
    - Suspicious modifications around text, dates, photographs, or official seals
    - Digital signatures and PKI certificate dictionaries in PDFs

    Always produces explainable diagnostics and avoids false certification.
    """

    def analyze_document(
        self,
        file_bytes: bytes,
        mime_type: str,
        document_id: str
    ) -> Dict[str, Any]:
        anomalies: List[str] = []
        visual_evidence: List[str] = []
        metadata_evidence: List[str] = []
        software_detected = None
        ela_score = 0.0
        ela_image_filename = None
        is_inconclusive = False
        ai_flag = False
        dig_sig_status = "No digital signature (Standard paper scan / raster)"

        file_size_kb = len(file_bytes) / 1024.0

        # Check for empty or severely truncated files
        if len(file_bytes) < 150:
            is_inconclusive = True
            visual_evidence.append("Severely truncated file size prevents compression analysis.")

        # 1. AI-Generation & Synthetic Imagery Screening
        ai_detected, ai_notes = self._screen_ai_generation(file_bytes, mime_type)
        if ai_detected:
            ai_flag = True
            anomalies.append(f"AI Generator indicator detected: {ai_detected}")
            metadata_evidence.extend(ai_notes)
        elif ai_notes:
            metadata_evidence.extend(ai_notes)

        # 2. Metadata / Software Inspection
        software_detected, meta_anomalies, dig_sig_present = self._inspect_metadata(file_bytes, mime_type)
        if software_detected:
            anomalies.append(f"Edited with software: {software_detected}")
            metadata_evidence.append(f"Editor metadata present: {software_detected}")
        if dig_sig_present:
            dig_sig_status = "Cryptographic digital signature detected (e-District / PKI certificate)"
            metadata_evidence.append("Valid PDF cryptographic signature dictionary detected (/Type /Sig)")
        else:
            metadata_evidence.append("Standard unsigned PDF/image (requires official manual verification)")

        anomalies.extend(meta_anomalies)

        # 3. PDF Structural & Font Layout Inspection
        if mime_type == "application/pdf":
            pdf_visual_flags = self._inspect_pdf_structure(file_bytes)
            if pdf_visual_flags:
                visual_evidence.extend(pdf_visual_flags)
                anomalies.extend(pdf_visual_flags)

        # 4. Forensic ELA (Error Level Analysis)
        if mime_type.startswith("image/"):
            ela_score, ela_path = self._perform_ela(file_bytes, document_id)
            if ela_path:
                ela_image_filename = os.path.basename(ela_path)
            if ela_score > 28.0:
                msg = f"High compression variance detected (ELA score {ela_score:.1f}). Possible localized editing or splice."
                anomalies.append(msg)
                visual_evidence.append(msg)
            elif ela_score > 0:
                visual_evidence.append(f"Uniform JPEG compression level verified (ELA score {ela_score:.1f}).")
        elif mime_type == "application/pdf":
            pdf_ela_score, ela_path = self._perform_pdf_ela(file_bytes, document_id)
            if pdf_ela_score > 0:
                ela_score = pdf_ela_score
                if ela_path:
                    ela_image_filename = os.path.basename(ela_path)
                if ela_score > 28.0:
                    msg = f"Page image compression discrepancy (ELA score {ela_score:.1f})."
                    anomalies.append(msg)
                    visual_evidence.append(msg)
                else:
                    visual_evidence.append(f"PDF raster layer exhibits consistent compression (ELA score {ela_score:.1f}).")

        # 5. Classify Authenticity Results
        if len(anomalies) > 0 or ai_flag:
            authenticity_result = "Potential manipulation detected"
            risk_level = "HIGH" if (ai_flag or len(anomalies) >= 2 or (software_detected and "photoshop" in software_detected.lower())) else "MEDIUM"
            explanation = (
                f"Potential manipulation or anomaly detected: {'; '.join(anomalies)}. "
                "Physical verification by designated authority required before processing."
            )
            is_flagged = True
        elif is_inconclusive:
            authenticity_result = "Inconclusive — further verification required"
            risk_level = "MEDIUM"
            explanation = (
                f"Forensic analysis is inconclusive due to limited file resolution ({file_size_kb:.1f} KB). "
                "The image does not contain sufficient pixel density to rule out or confirm manipulation. "
                "Physical inspection or re-scan at 300 DPI recommended."
            )
            is_flagged = False
        else:
            authenticity_result = "No obvious manipulation detected"
            risk_level = "LOW"
            explanation = (
                "Document exhibits uniform compression, standard metadata structure, and consistent visual layouts. "
                "Advisory note: Absence of detected anomalies does not constitute official government authenticity certification."
            )
            is_flagged = False

        ai_status = "Potential synthetic/generative artifacts detected" if ai_flag else (
            "Inconclusive" if is_inconclusive else "No synthetic generative signatures identified"
        )

        return {
            "is_flagged": is_flagged,
            "risk_level": risk_level,
            "authenticity_result": authenticity_result,
            "ai_generation_screening": ai_status,
            "digital_signature_status": dig_sig_status,
            "ela_score": round(ela_score, 2),
            "software_detected": software_detected,
            "detected_anomalies": anomalies,
            "visual_structure_evidence": visual_evidence,
            "metadata_evidence": metadata_evidence,
            "explanation": explanation,
            "ela_artifact_path": ela_image_filename
        }

    def _screen_ai_generation(self, data: bytes, mime_type: str) -> Tuple[Optional[str], List[str]]:
        """Screens for synthetic AI generation clues in EXIF, metadata, and byte streams."""
        notes = []
        lower = data[:8192].lower() + data[-8192:].lower()
        for kw in AI_GENERATOR_KEYWORDS:
            if kw.encode() in lower:
                notes.append(f"AI generation engine signature found in binary stream: '{kw}'")
                return kw.title(), notes
        
        # Check EXIF parameters if image
        if mime_type.startswith("image/"):
            try:
                img = Image.open(io.BytesIO(data))
                info = getattr(img, "info", {}) or {}
                for k, v in info.items():
                    val_str = str(v).lower()
                    for kw in AI_GENERATOR_KEYWORDS:
                        if kw in val_str:
                            notes.append(f"AI generator metadata tag detected: '{kw}' in tag '{k}'")
                            return kw.title(), notes
            except Exception:
                pass

        return None, notes

    def _inspect_metadata(self, data: bytes, mime_type: str) -> Tuple[Optional[str], List[str], bool]:
        anomalies = []
        detected_software = None
        has_digital_signature = False

        if mime_type == "application/pdf":
            lower_head = data[:8192].lower() + data[-16384:].lower()
            for kw in SUSPICIOUS_SOFTWARE_KEYWORDS:
                if kw.encode() in lower_head:
                    detected_software = kw.title()
                    break

            # Digital signature check
            if b"/type /sig" in lower_head or b"/adbe.pkcs7.detached" in lower_head or b"/byte_range" in lower_head:
                has_digital_signature = True

            # Multiple revisions / EOF count
            eof_count = data.count(b"%%EOF")
            if eof_count > 3:
                anomalies.append(f"Multiple PDF revision markers detected ({eof_count} updates; possible post-issue edit).")

            # Creation date vs Modification date mismatch check
            try:
                mod_match = re.search(rb"/ModDate\s*\(D:(\d{4})", data)
                create_match = re.search(rb"/CreationDate\s*\(D:(\d{4})", data)
                if mod_match and create_match:
                    mod_yr = int(mod_match.group(1))
                    create_yr = int(create_match.group(1))
                    if abs(mod_yr - create_yr) > 2 and detected_software:
                        anomalies.append(f"Significant timestamp divergence: Created in {create_yr}, modified in {mod_yr} with {detected_software}.")
            except Exception:
                pass

        elif mime_type.startswith("image/"):
            lower_bytes = data.lower()
            for kw in SUSPICIOUS_SOFTWARE_KEYWORDS:
                if kw.encode() in lower_bytes:
                    detected_software = kw.title()
                    break

            try:
                img = Image.open(io.BytesIO(data))
                info = img.info or {}
                software = info.get("Software") or info.get("software")
                if software and not detected_software:
                    for kw in SUSPICIOUS_SOFTWARE_KEYWORDS:
                        if kw in str(software).lower():
                            detected_software = str(software)
                            break
            except Exception:
                pass

        return detected_software, anomalies, has_digital_signature

    def _inspect_pdf_structure(self, pdf_bytes: bytes) -> List[str]:
        """Inspects PDF visual layout, fonts, and structural consistency using PyMuPDF."""
        flags = []
        try:
            import fitz
            doc = fitz.open(stream=pdf_bytes, filetype="pdf")
            if len(doc) > 0:
                page = doc[0]
                fonts = page.get_fonts()
                # Check for suspicious font subsets or mixing vector fonts over raster scanned forms
                has_raster_images = len(page.get_images()) > 0
                has_vector_text = len(page.get_text().strip()) > 50

                # If a document has a large raster image (scanned form) AND small vector text overlays on top,
                # this is a common indicator of text added on top of a scanned certificate
                if has_raster_images and has_vector_text and len(fonts) > 4:
                    flags.append("Mixed vector text overlay detected on scanned raster form (indicative of digital text insertion).")

            doc.close()
        except Exception:
            pass
        return flags

    def _perform_ela(self, img_bytes: bytes, document_id: str, quality: int = 90) -> Tuple[float, str]:
        """
        Executes Error Level Analysis (ELA):
        Re-saves image at specified quality and compares pixel delta.
        """
        try:
            original = Image.open(io.BytesIO(img_bytes)).convert("RGB")
            
            # Recompress in-memory
            buffer = io.BytesIO()
            original.save(buffer, "JPEG", quality=quality)
            buffer.seek(0)
            recompressed = Image.open(buffer)

            # Compute absolute difference
            diff = ImageChops.difference(original, recompressed)
            
            # Enhance difference for visual artifact rendering
            extrema = diff.getextrema()
            max_diff = max([ex[1] for ex in extrema])
            scale = 255.0 / max_diff if max_diff > 0 else 1.0
            enhanced = ImageEnhance.Brightness(diff).enhance(scale)

            # Calculate average anomaly score
            gray_diff = diff.convert("L")
            stat = getattr(gray_diff, "get_flattened_data", gray_diff.getdata)()
            avg_diff = sum(stat) / len(stat) if len(stat) > 0 else 0.0

            # Save ELA visualization artifact
            artifact_name = f"ela_{document_id}_{uuid.uuid4().hex[:8]}.jpg"
            artifact_dir = settings.STORAGE_ROOT / "ela_cache"
            os.makedirs(artifact_dir, exist_ok=True)
            artifact_path = artifact_dir / artifact_name
            enhanced.save(artifact_path, "JPEG")

            return avg_diff, str(artifact_path)
        except Exception:
            return 0.0, ""

    def _perform_pdf_ela(self, pdf_bytes: bytes, document_id: str) -> Tuple[float, str]:
        try:
            import fitz
            doc = fitz.open(stream=pdf_bytes, filetype="pdf")
            if len(doc) > 0:
                pix = doc[0].get_pixmap(dpi=150)
                img_bytes = pix.tobytes("png")
                doc.close()
                return self._perform_ela(img_bytes, document_id)
        except Exception:
            pass
        return 0.0, ""

tampering_detector = TamperingDetector()
